import { randomUUID } from "crypto";
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrdersController,
  PaymentsController,
} from "@paypal/paypal-server-sdk";
import { env } from "../config/env";
import { logger } from "../observability/logger";
import { AppError } from "../utils/AppError";

// Everything this app does with PayPal goes through this file.
//
//  Orders + Payments (create, capture, look up a capture, refund) use
//  PayPal's official TypeScript Server SDK (@paypal/paypal-server-sdk,
//  generated by APIMatic; written with the APIMatic Context Plugin).
//
//  Disputes + webhook verification aren't in that SDK, so they call the
//  REST endpoints directly (Disputes API v1, Notifications API v1).
//
// No PAYPAL_CLIENT_ID / PAYPAL_CLIENT_SECRET → an in-memory simulator stands
// in for PayPal so the app still runs end to end. The UI always shows which.

export type PaypalMode = "sandbox" | "simulated";

export function paypalMode(): PaypalMode {
  return env.PAYPAL_CLIENT_ID && env.PAYPAL_CLIENT_SECRET ? "sandbox" : "simulated";
}

export interface CaptureResult {
  captureId: string;
  status: string;
  amount: number;
  currency: string;
  payerEmail: string | null;
}

export interface CaptureDetails {
  captureId: string;
  status: string; // COMPLETED, PARTIALLY_REFUNDED, REFUNDED, ...
  amount: number;
  currency: string;
  createTime: string;
}

export interface RefundResult {
  refundId: string;
  status: string;
  amount: number;
  currency: string;
}

const money = (n: number) => n.toFixed(2);

// ── PayPal Server SDK client (built once, reused) ────────────────────────

let sdkClient: Client | null = null;

function sdk(): Client {
  if (!sdkClient) {
    sdkClient = new Client({
      clientCredentialsAuthCredentials: {
        oAuthClientId: env.PAYPAL_CLIENT_ID!,
        oAuthClientSecret: env.PAYPAL_CLIENT_SECRET!,
        oAuthClockSkew: 60, // refresh the token a minute before it expires
      },
      environment: env.PAYPAL_API_BASE.includes("sandbox") ? Environment.Sandbox : Environment.Production,
      // SDK defaults are "no timeout, no retries". Retries stay on GET/PUT
      // only (the SDK default); POSTs are protected by PayPal-Request-Id.
      timeout: 30000,
      httpClientOptions: { timeout: 30000, retryConfig: { maxNumberOfRetries: 2, backoffFactor: 2 } },
    });
  }
  return sdkClient;
}

// Turn an SDK ApiError into our AppError, keeping PayPal's issue code.
function fromSdkError(err: unknown, what: string): never {
  if (err instanceof ApiError) {
    let issue = `HTTP ${err.statusCode}`;
    try {
      const payload = (err.result ?? (typeof err.body === "string" ? JSON.parse(err.body) : null)) as any;
      issue = payload?.details?.[0]?.issue ?? payload?.name ?? issue;
      logger.error({ status: err.statusCode, issue, debugId: payload?.debug_id }, `PayPal ${what} failed`);
    } catch {
      logger.error({ status: err.statusCode }, `PayPal ${what} failed`);
    }
    throw new AppError(502, "PAYPAL_ERROR", `PayPal rejected the ${what} (${issue}).`);
  }
  throw err;
}

// ── Raw REST (for APIs the SDK doesn't cover) ────────────────────────────

let cachedToken: { value: string; expiresAt: number } | null = null;

async function getAccessToken(): Promise<string> {
  if (cachedToken && cachedToken.expiresAt > Date.now() + 60_000) return cachedToken.value;
  const basic = Buffer.from(`${env.PAYPAL_CLIENT_ID}:${env.PAYPAL_CLIENT_SECRET}`).toString("base64");
  const res = await fetch(`${env.PAYPAL_API_BASE}/v1/oauth2/token`, {
    method: "POST",
    headers: { Authorization: `Basic ${basic}`, "Content-Type": "application/x-www-form-urlencoded" },
    body: "grant_type=client_credentials",
  });
  if (!res.ok) {
    logger.error({ status: res.status }, "PayPal OAuth token request failed");
    throw new AppError(502, "PAYPAL_AUTH_FAILED", "Could not authenticate with PayPal. Check the sandbox credentials.");
  }
  const json = (await res.json()) as { access_token: string; expires_in: number };
  cachedToken = { value: json.access_token, expiresAt: Date.now() + json.expires_in * 1000 };
  return json.access_token;
}

async function paypalRest<T>(
  path: string,
  init: { method: string; body?: unknown; form?: FormData; requestId?: string }
): Promise<T> {
  const headers: Record<string, string> = { Authorization: `Bearer ${await getAccessToken()}` };
  if (!init.form) headers["Content-Type"] = "application/json";
  if (init.requestId) headers["PayPal-Request-Id"] = init.requestId;
  const res = await fetch(`${env.PAYPAL_API_BASE}${path}`, {
    method: init.method,
    headers,
    body: init.form ?? (init.body ? JSON.stringify(init.body) : undefined),
  });
  const text = await res.text();
  const json = text ? JSON.parse(text) : {};
  if (!res.ok) {
    const detail = json?.details?.[0]?.issue ?? json?.name ?? `HTTP ${res.status}`;
    logger.error({ status: res.status, path, detail, debugId: json?.debug_id }, "PayPal REST call failed");
    throw new AppError(502, "PAYPAL_ERROR", `PayPal rejected the request (${detail}).`);
  }
  return json as T;
}

// ── Simulator ────────────────────────────────────────────────────────────

interface SimCapture {
  amount: number;
  currency: string;
  refunded: number;
  createTime: string;
}
const simOrders = new Map<string, { amount: number; currency: string }>();
const simCaptures = new Map<string, SimCapture>();
const simId = (prefix: string) => `${prefix}-SIM-${randomUUID().slice(0, 8).toUpperCase()}`;

// The simulator keeps state in memory, so after a restart it rebuilds a
// capture from our saved order. No-op when talking to real PayPal.
export function ensureSimulatedCapture(order: {
  captureId: string | null;
  total: number;
  currency: string;
  refundedTotal: number;
  paidAt: Date | null;
}) {
  if (paypalMode() !== "simulated" || !order.captureId || simCaptures.has(order.captureId)) return;
  simCaptures.set(order.captureId, {
    amount: order.total,
    currency: order.currency,
    refunded: order.refundedTotal,
    createTime: (order.paidAt ?? new Date()).toISOString(),
  });
}

// ── Orders & payments (SDK) ──────────────────────────────────────────────

export async function createOrder(input: {
  referenceId: string;
  description: string;
  amount: number;
  currency: string;
}): Promise<{ paypalOrderId: string }> {
  if (paypalMode() === "simulated") {
    const id = simId("ORDER");
    simOrders.set(id, { amount: input.amount, currency: input.currency });
    return { paypalOrderId: id };
  }
  try {
    const { result } = await new OrdersController(sdk()).createOrder({
      body: {
        intent: CheckoutPaymentIntent.Capture,
        purchaseUnits: [
          {
            referenceId: input.referenceId,
            customId: input.referenceId,
            description: input.description.slice(0, 127),
            amount: { currencyCode: input.currency, value: money(input.amount) },
          },
        ],
      },
      paypalRequestId: `create-${input.referenceId}`,
      prefer: "return=minimal",
    });
    if (!result.id) throw new AppError(502, "PAYPAL_ERROR", "PayPal did not return an order id.");
    return { paypalOrderId: result.id };
  } catch (err) {
    fromSdkError(err, "order creation");
  }
}

export async function captureOrder(paypalOrderId: string): Promise<CaptureResult> {
  if (paypalMode() === "simulated") {
    const order = simOrders.get(paypalOrderId);
    if (!order) throw new AppError(404, "NOT_FOUND", "Simulated PayPal order not found.");
    const captureId = simId("CAPTURE");
    simCaptures.set(captureId, { ...order, refunded: 0, createTime: new Date().toISOString() });
    return { captureId, status: "COMPLETED", amount: order.amount, currency: order.currency, payerEmail: "buyer@simulated.paypal" };
  }
  try {
    const { result } = await new OrdersController(sdk()).captureOrder({
      id: paypalOrderId,
      paypalRequestId: `capture-${paypalOrderId}`,
      prefer: "return=representation",
    });
    const capture = result.purchaseUnits?.[0]?.payments?.captures?.[0];
    if (!capture?.id || !capture.amount) throw new AppError(502, "PAYPAL_ERROR", "PayPal did not return a capture.");
    return {
      captureId: capture.id,
      status: String(capture.status ?? "UNKNOWN"),
      amount: Number(capture.amount.value),
      currency: capture.amount.currencyCode,
      payerEmail: result.payer?.emailAddress ?? null,
    };
  } catch (err) {
    fromSdkError(err, "payment capture");
  }
}

// Live lookup used by the agents, so decisions use what PayPal says now.
export async function getCaptureDetails(captureId: string): Promise<CaptureDetails> {
  if (paypalMode() === "simulated") {
    const c = simCaptures.get(captureId);
    if (!c) throw new AppError(404, "NOT_FOUND", "Simulated PayPal capture not found.");
    const status = c.refunded <= 0 ? "COMPLETED" : c.refunded >= c.amount ? "REFUNDED" : "PARTIALLY_REFUNDED";
    return { captureId, status, amount: c.amount, currency: c.currency, createTime: c.createTime };
  }
  try {
    const { result } = await new PaymentsController(sdk()).getCapturedPayment({ captureId });
    return {
      captureId: result.id ?? captureId,
      status: String(result.status ?? "UNKNOWN"),
      amount: Number(result.amount?.value ?? 0),
      currency: result.amount?.currencyCode ?? env.PAYPAL_CURRENCY,
      createTime: result.createTime ?? new Date().toISOString(),
    };
  } catch (err) {
    fromSdkError(err, "capture lookup");
  }
}

export async function refundCapture(input: {
  captureId: string;
  amount: number;
  currency: string;
  note: string;
  idempotencyKey: string;
}): Promise<RefundResult> {
  if (paypalMode() === "simulated") {
    const c = simCaptures.get(input.captureId);
    if (!c) throw new AppError(404, "NOT_FOUND", "Simulated PayPal capture not found.");
    if (c.refunded + input.amount > c.amount + 0.001) {
      throw new AppError(422, "PAYPAL_ERROR", "PayPal rejected the refund (REFUND_AMOUNT_EXCEEDED).");
    }
    c.refunded += input.amount;
    return { refundId: simId("REFUND"), status: "COMPLETED", amount: input.amount, currency: input.currency };
  }
  try {
    const { result } = await new PaymentsController(sdk()).refundCapturedPayment({
      captureId: input.captureId,
      paypalRequestId: input.idempotencyKey,
      prefer: "return=representation",
      body: {
        amount: { currencyCode: input.currency, value: money(input.amount) },
        noteToPayer: input.note.slice(0, 255),
      },
    });
    return {
      refundId: result.id ?? "unknown",
      status: String(result.status ?? "UNKNOWN"),
      amount: Number(result.amount?.value ?? input.amount),
      currency: result.amount?.currencyCode ?? input.currency,
    };
  } catch (err) {
    fromSdkError(err, "refund");
  }
}

// ── Disputes (REST v1) ───────────────────────────────────────────────────

export interface DisputeSnapshot {
  disputeId: string;
  reason: string; // MERCHANDISE_OR_SERVICE_NOT_RECEIVED, UNAUTHORISED, ...
  status: string; // OPEN, WAITING_FOR_SELLER_RESPONSE, UNDER_REVIEW, RESOLVED, ...
  stage: string; // INQUIRY, CHARGEBACK, PRE_ARBITRATION, ARBITRATION
  amount: number;
  currency: string;
  sellerResponseDue: string | null;
  createTime: string;
  updateTime: string;
  transactionId: string | null; // the seller's capture id
  buyerName: string | null;
  messages: { postedBy: string; time: string; content: string }[];
  outcome: { code: string; amountRefunded: number | null } | null;
  actions: string[]; // what PayPal allows right now (from HATEOAS links)
}

function normalizeDispute(d: any): DisputeSnapshot {
  const tx = d.disputed_transactions?.[0] ?? {};
  return {
    disputeId: d.dispute_id,
    reason: d.reason ?? "OTHER",
    status: d.status ?? "OPEN",
    stage: d.dispute_life_cycle_stage ?? "INQUIRY",
    amount: Number(d.dispute_amount?.value ?? 0),
    currency: d.dispute_amount?.currency_code ?? env.PAYPAL_CURRENCY,
    sellerResponseDue: d.seller_response_due_date ?? null,
    createTime: d.create_time ?? new Date().toISOString(),
    updateTime: d.update_time ?? new Date().toISOString(),
    transactionId: tx.seller_transaction_id ?? null,
    buyerName: tx.buyer?.name ?? null,
    messages: (d.messages ?? []).map((m: any) => ({ postedBy: m.posted_by, time: m.time_posted, content: m.content })),
    outcome: d.dispute_outcome
      ? {
          code: d.dispute_outcome.outcome_code,
          amountRefunded: d.dispute_outcome.amount_refunded ? Number(d.dispute_outcome.amount_refunded.value) : null,
        }
      : null,
    actions: (d.links ?? []).map((l: any) => l.rel).filter((r: string) => r && r !== "self"),
  };
}

// Simulated disputes look exactly like PayPal's JSON so the same code reads both.
const simDisputes = new Map<string, any>();

function simLinks(status: string, stage: string) {
  if (status === "RESOLVED") return [];
  if (status === "UNDER_REVIEW") return ["adjudicate"];
  const rels = ["accept_claim", "provide_evidence", "send_message"];
  if (stage === "INQUIRY") rels.push("make_offer", "escalate");
  return rels;
}

function simSetStatus(d: any, status: string, stage?: string) {
  d.status = status;
  if (stage) d.dispute_life_cycle_stage = stage;
  d.update_time = new Date().toISOString();
  d.links = simLinks(d.status, d.dispute_life_cycle_stage).map((rel) => ({ rel }));
}

export function createSimulatedDispute(input: {
  captureId: string;
  amount: number;
  currency: string;
  reason: string;
  buyerName: string;
  buyerMessage: string;
}): any {
  const now = new Date();
  const d: any = {
    dispute_id: `PP-D-SIM-${randomUUID().slice(0, 6).toUpperCase()}`,
    create_time: now.toISOString(),
    update_time: now.toISOString(),
    reason: input.reason,
    status: "WAITING_FOR_SELLER_RESPONSE",
    dispute_life_cycle_stage: "INQUIRY",
    dispute_channel: "INTERNAL",
    dispute_amount: { currency_code: input.currency, value: money(input.amount) },
    seller_response_due_date: new Date(now.getTime() + 10 * 86_400_000).toISOString(),
    disputed_transactions: [{ seller_transaction_id: input.captureId, buyer: { name: input.buyerName } }],
    messages: [{ posted_by: "BUYER", time_posted: now.toISOString(), content: input.buyerMessage }],
  };
  simSetStatus(d, d.status);
  simDisputes.set(d.dispute_id, d);
  return d;
}

// Rebuild a simulated dispute from our database copy after a restart.
export function restoreSimulatedDispute(raw: any) {
  if (paypalMode() === "simulated" && raw?.dispute_id && !simDisputes.has(raw.dispute_id)) {
    simDisputes.set(raw.dispute_id, structuredClone(raw));
  }
}

function simDisputeOr404(id: string) {
  const d = simDisputes.get(id);
  if (!d) throw new AppError(404, "NOT_FOUND", "Simulated dispute not found.");
  return d;
}

export async function getDisputeRaw(disputeId: string): Promise<any> {
  if (paypalMode() === "simulated") return structuredClone(simDisputeOr404(disputeId));
  return paypalRest<any>(`/v1/customer/disputes/${encodeURIComponent(disputeId)}`, { method: "GET" });
}

export async function getDispute(disputeId: string): Promise<DisputeSnapshot> {
  return normalizeDispute(await getDisputeRaw(disputeId));
}

export async function listDisputeIds(): Promise<string[]> {
  if (paypalMode() === "simulated") return [...simDisputes.keys()];
  const res = await paypalRest<any>(`/v1/customer/disputes?page_size=50`, { method: "GET" });
  return (res.items ?? []).map((i: any) => i.dispute_id as string);
}

export { normalizeDispute };

// Refund the buyer and close the dispute in their favour.
export async function acceptDisputeClaim(disputeId: string, note: string, amount: number | null, currency: string) {
  if (paypalMode() === "simulated") {
    const d = simDisputeOr404(disputeId);
    const refunded = amount ?? Number(d.dispute_amount.value);
    d.dispute_outcome = { outcome_code: "RESOLVED_BUYER_FAVOUR", amount_refunded: { currency_code: currency, value: money(refunded) } };
    d.messages.push({ posted_by: "SELLER", time_posted: new Date().toISOString(), content: note });
    simSetStatus(d, "RESOLVED");
    return;
  }
  await paypalRest(`/v1/customer/disputes/${encodeURIComponent(disputeId)}/accept-claim`, {
    method: "POST",
    requestId: `accept-${disputeId}`,
    body: {
      note: note.slice(0, 2000),
      ...(amount !== null ? { refund_amount: { currency_code: currency, value: money(amount) } } : {}),
    },
  });
}

// Offer a partial refund to settle an inquiry.
export async function makeDisputeOffer(disputeId: string, note: string, amount: number, currency: string) {
  if (paypalMode() === "simulated") {
    const d = simDisputeOr404(disputeId);
    d.offer = { seller_offered_amount: { currency_code: currency, value: money(amount) }, offer_type: "REFUND" };
    d.messages.push({ posted_by: "SELLER", time_posted: new Date().toISOString(), content: note });
    simSetStatus(d, "WAITING_FOR_BUYER_RESPONSE");
    return;
  }
  await paypalRest(`/v1/customer/disputes/${encodeURIComponent(disputeId)}/make-offer`, {
    method: "POST",
    requestId: `offer-${disputeId}-${money(amount)}`,
    body: { note: note.slice(0, 2000), offer_amount: { currency_code: currency, value: money(amount) }, offer_type: "REFUND" },
  });
}

// Contest the dispute: send our written case plus an evidence file.
export async function provideDisputeEvidence(disputeId: string, notes: string, evidenceText: string) {
  if (paypalMode() === "simulated") {
    const d = simDisputeOr404(disputeId);
    d.evidences = [...(d.evidences ?? []), { evidence_type: "OTHER", notes, date: new Date().toISOString() }];
    d.messages.push({ posted_by: "SELLER", time_posted: new Date().toISOString(), content: notes });
    simSetStatus(d, "UNDER_REVIEW", d.dispute_life_cycle_stage === "INQUIRY" ? "CHARGEBACK" : undefined);
    return;
  }
  const form = new FormData();
  form.append(
    "input",
    new Blob([JSON.stringify({ evidences: [{ evidence_type: "OTHER", notes: notes.slice(0, 2000) }] })], {
      type: "application/json",
    })
  );
  form.append("evidence-file", new Blob([evidenceText], { type: "text/plain" }), "paydesk-evidence.txt");
  await paypalRest(`/v1/customer/disputes/${encodeURIComponent(disputeId)}/provide-evidence`, { method: "POST", form });
}

// Sandbox only: make PayPal decide a dispute that's under review.
export async function adjudicateDispute(disputeId: string, outcome: "BUYER_FAVOR" | "SELLER_FAVOR") {
  if (paypalMode() === "simulated") {
    const d = simDisputeOr404(disputeId);
    d.dispute_outcome =
      outcome === "SELLER_FAVOR"
        ? { outcome_code: "RESOLVED_SELLER_FAVOUR" }
        : { outcome_code: "RESOLVED_BUYER_FAVOUR", amount_refunded: d.dispute_amount };
    simSetStatus(d, "RESOLVED");
    return;
  }
  await paypalRest(`/v1/customer/disputes/${encodeURIComponent(disputeId)}/adjudicate`, {
    method: "POST",
    body: { adjudication_outcome: outcome },
  });
}

// ── Webhooks ─────────────────────────────────────────────────────────────

// Asks PayPal to confirm a webhook really came from PayPal.
export async function verifyWebhookSignature(headers: Record<string, string | undefined>, event: unknown) {
  if (!env.PAYPAL_WEBHOOK_ID) return false;
  const res = await paypalRest<{ verification_status: string }>("/v1/notifications/verify-webhook-signature", {
    method: "POST",
    body: {
      auth_algo: headers["paypal-auth-algo"],
      cert_url: headers["paypal-cert-url"],
      transmission_id: headers["paypal-transmission-id"],
      transmission_sig: headers["paypal-transmission-sig"],
      transmission_time: headers["paypal-transmission-time"],
      webhook_id: env.PAYPAL_WEBHOOK_ID,
      webhook_event: event,
    },
  });
  return res.verification_status === "SUCCESS";
}
